const item = $input.first();

// Extract text from OpenAI PDF extraction response
let extractedText = '';
if (item.json.message && item.json.message.content) {
  extractedText = item.json.message.content;
} else if (item.json.choices && item.json.choices[0]) {
  extractedText = item.json.choices[0].message.content;
} else {
  extractedText = JSON.stringify(item.json);
}

// Pull file metadata from the Drive Trigger node
const driveData = $('Google Drive — Watch Submissions Folder').first().json;

// Parse student info from filename
// Required format: FirstLast__email@domain.com__Assignment_Title__Course.pdf
const fileName = driveData.name || 'submission.pdf';
const nameParts = fileName.replace('.pdf', '').split('__');

const studentName = nameParts[0] ? nameParts[0].replace(/_/g, ' ') : 'Unknown Student';
const studentEmail = nameParts[1] || '';
const assignmentTitle = nameParts[2] ? nameParts[2].replace(/_/g, ' ') : 'Untitled Assignment';
const course = nameParts[3] ? nameParts[3].replace(/_/g, ' ') : 'General';

// Set your rubric Google Doc ID below
const rubricDocId = 'YOUR_RUBRIC_GOOGLE_DOC_ID';

return [{
  json: {
    student_name: studentName,
    student_email: studentEmail,
    assignment_title: assignmentTitle,
    course: course,
    rubric_doc_id: rubricDocId,
    assignment_text: extractedText,
    submission_timestamp: new Date().toISOString(),
    file_name: fileName
  }
}];

const item = $input.first();

// Extract the raw content from OpenAI response
let rawContent = '';
if (item.json.message && item.json.message.content) {
  rawContent = item.json.message.content;
} else if (item.json.choices && item.json.choices[0]) {
  rawContent = item.json.choices[0].message.content;
} else {
  rawContent = JSON.stringify(item.json);
}

// Strip markdown code fences if present
const cleaned = rawContent
  .replace(/```json\n?/gi, '')
  .replace(/```\n?/gi, '')
  .trim();

let gradeData;
try {
  gradeData = JSON.parse(cleaned);
} catch(e) {
  gradeData = {
    total_score: 0,
    grade_letter: 'N/A',
    rubric_breakdown: {
      coverage:    { score: 0, comment: 'Parse error — please review manually.' },
      accuracy:    { score: 0, comment: 'Parse error — please review manually.' },
      depth:       { score: 0, comment: 'Parse error — please review manually.' },
      originality: { score: 0, comment: 'Parse error — please review manually.' }
    },
    feedback_paragraph_1: 'Unable to parse the AI grade response. Please review manually.',
    feedback_paragraph_2: 'System error: ' + e.message,
    feedback_paragraph_3: 'Please contact your instructor for your grade.'
  };
}

const studentData = $('Code — Parse Filename Metadata').first().json;

return [{
  json: {
    ...studentData,
    ...gradeData,
    graded_at: new Date().toISOString()
  }
}];

const items = $input.all();

const todayStr = new Date().toISOString().slice(0, 10);

const todayItems = items.filter(i => {
  const ts = i.json['Timestamp'] || '';
  return ts.startsWith(todayStr);
});

if (!todayItems || todayItems.length === 0) {
  return [{
    json: {
      has_submissions: false,
      summary_date: new Date().toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'full' }),
      total_count: 0,
      avg_score: 0,
      grade_distribution: { A: 0, B: 0, C: 0, D: 0, F: 0 }
    }
  }];
}

const scores = todayItems.map(i => parseFloat(i.json['Total Score']) || 0);
const avgScore = (scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(1);

const gradeRows = todayItems.map(i =>
  `• ${i.json['Student Name']} — ${i.json['Assignment Title']} — ${i.json['Total Score']}/100 (${i.json['Grade Letter']})`
).join('\n');

return [{
  json: {
    has_submissions: true,
    summary_date: new Date().toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'full' }),
    total_count: todayItems.length,
    avg_score: avgScore,
    grade_rows: gradeRows,
    grade_distribution: {
      A: todayItems.filter(i => i.json['Grade Letter'] === 'A').length,
      B: todayItems.filter(i => i.json['Grade Letter'] === 'B').length,
      C: todayItems.filter(i => i.json['Grade Letter'] === 'C').length,
      D: todayItems.filter(i => i.json['Grade Letter'] === 'D').length,
      F: todayItems.filter(i => i.json['Grade Letter'] === 'F').length
    }
  }
}];
